-- PT107-S1-Q2. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT107-S1-Q2$batch05$ AND q.stimulus=$batch05$Politician: The funding for the new nationwide health-awareness campaign should come from an increase in taxes on cigarettes. It is well established that cigarette smoking causes many serious health problems, and it is only reasonable that people whose unhealthful habits cause so many health problems should bear the costs of that campaign.

Smoker: But it is equally well established that regularly eating high-fat, high-cholesterol foods causes as many serious health problems as does smoking, yet it would be manifestly unreasonable to force those who purchase such foods to bear the burden of financing this campaign.$batch05$ AND q.prompt=$batch05$The smoker's response to the politician's argument$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT107-S1-Q2$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT107-S1-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Smoker, implied) The politician's reasoning for taxing cigarettes does not hold up.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$High-fat, high-cholesterol foods cause just as many health problems, yet it would clearly be unreasonable to make people who buy them fund the campaign.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The politician's principle is that people whose habits cause health problems should pay. The smoker finds a case that fits the principle perfectly (fatty foods) but where applying it seems absurd. One case where a principle gives the wrong answer is a counterexample.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A counterexample to the politician's reasoning.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT107-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Fatty-food buyers are the counterexample. They meet the politician's standard, yet making them pay is "manifestly unreasonable," which calls the principle itself into question.$batch05$), ($batch05$B$batch05$, $batch05$The smoker proposes no other way to fund the campaign.$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. But the smoker never says the cigarette tax would raise too little money. The objection is about fairness, not whether the plan works.$batch05$), ($batch05$D$batch05$, $batch05$The smoker accepts that smoking causes serious health problems ("equally well established").$batch05$), ($batch05$E$batch05$, $batch05$No one says the tax would make health problems worse.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT107-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
